{
  "character_storylines": [
    {
      "id": "protagonist_main_line",
      "character_name": "苏晴",
      "line_type": "主角成长线",
      "importance": "main",
      "decision": "keep",
      "summary": "苏晴从独自承受双重身份压力的文静学霸，经历身份暴露危机、规则博弈、内部权力斗争、闺蜜误会与背叛打击，最终在最低谷后重整旗鼓，用智慧与勇气击败陈锋、收服刘伯、赢得林瑶信任，完成从规则遵守者到规则制定者的蜕变，建立新帮规，获得内心和解。",
      "linked_beats": [1,2,3,4,5,6,8,9,10,11,12,13,14,15],
      "episode_distribution": [
        {
          "episode_range": "1",
          "function": "展示双重身份与日常伪装，埋下身份暴露种子和规则怪谈机制。",
          "event": "苏晴在图书馆处理帮务后伪装成普通学生，巧妙应付林瑶的怀疑；在刘伯试探时利用监控盲区避开；破解陈锋的规则陷阱救回手下，但启用暗线，林瑶妈妈看到异常。",
          "relation_to_beat": "对应第1、2、3节拍：开场、主体呈现、铺垫"
        },
        {
          "episode_range": "2",
          "function": "身份危机升级，苏晴被迫主动出击，情感冲突激化。",
          "event": "学校谣言四起，陈锋利用林瑶送威胁信；天台谈判保护林瑶导致关系破裂；苏晴决定违反自己设定的规则启用黑客技术，宣告进入黑帮核心战场。",
          "relation_to_beat": "对应第4、5、6节拍：推动催化剂、争执、第二幕衔接点"
        },
        {
          "episode_range": "3",
          "function": "与陈锋的规则攻防战，展现大女主智勇双全。",
          "event": "陈锋绑架手下设狙击陷阱，苏晴用替身计策从水下潜入救出手下，反杀枪手并比剪刀手挑衅监控。同时识破林瑶被利用，心痛但不动声色。",
          "relation_to_beat": "对应第7、8节拍：B故事线（林瑶视角）、游戏及斗争"
        },
        {
          "episode_range": "4",
          "function": "中点高潮，身份在校园舞会接近暴露，苏晴用录音反击，但违反帮规被刘伯质问，警方介入。",
          "event": "舞会上陈锋准备揭穿身份，苏晴播放录音反制，飞踢夺枪，勉强圆场；将证据U盘塞给林瑶让她报警；刘伯带人包围，指控违反帮规；苏晴被警方带走前对林瑶挤眼。",
          "relation_to_beat": "对应第9、10节拍：中点、危险逼近"
        },
        {
          "episode_range": "5",
          "function": "进入灵魂黑夜，失去一切后重新找到目标。",
          "event": "被刘伯剥夺老大位置，交出信物；林瑶被陈锋残党绑架；苏晴狼狈回家，几乎放弃，但收到林瑶求救定位后重燃斗志。",
          "relation_to_beat": "对应第11、12节拍：一败涂地、灵魂黑夜"
        },
        {
          "episode_range": "6",
          "function": "最终决战，整合资源制定新规则，击败陈锋，收服刘伯，修复与林瑶的关系。",
          "event": "用录音笔威胁刘伯合作；联合警方突袭据点；当警察面播放陈锋犯罪证据并洗清自己；宣布重组青帮废除旧规则；与林瑶达成信任。",
          "relation_to_beat": "对应第13、14、15节拍：第三幕衔接点、结局、终场画面"
        }
      ],
      "detailed_storyline": "苏晴的故事线从日常伪装开始，她同时是学霸和黑帮老大，但林瑶的怀疑、刘伯的试探、陈锋的规则陷阱层层加压。第一幕她被动防守，利用规则漏洞挽回局面但埋下隐患。第二幕她主动进攻，在舞会上以超高智勇反击陈锋，却因违反帮规被刘伯借口夺权，同时林瑶被绑，陷入众叛亲离的绝境。灵魂黑夜中她反思为何而战，林瑶的信任让她重新振作。第三幕她跳出旧规则，用录音证据联合警方，一举端掉陈锋，并迫使刘伯臣服。最终她成为新帮规的创立者，获得内心和解与林瑶的忠诚伙伴。",
      "edit_notes": "这条线保留完整，是剧本核心。需注意每集苏晴必须有高光反转，确保大女主主导性。与陈锋的规则博弈要体现层层升级的异常感，满足用户对规则怪谈的偏好。林瑶误会与修复需贯穿始终，强化都市情感冲突。节拍14中苏晴洗白自己的手法需谨慎处理，避免法律逻辑漏洞。"
    },
